/// Complete withdrawal request and state management
#[derive(Clone, Debug)]
pub struct WithdrawalRequestPipeline {
    pub account_index: u64,           // Account in L2 state tree
    pub amount: u64,                  // Withdrawal amount (sompi)
    pub kaspa_destination: [u8; 34], // L1 destination address
    pub requested_epoch: u64,         // Epoch withdrawal requested
    pub status: WithdrawalStatus,
    pub inscription: Option<WithdrawalInscription>, // L1 inscription data
}

/// L1 Withdrawal Inscription - embedded in withdrawal UTXO (96 bytes)
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct WithdrawalInscription {
    pub epoch: u64,                  // 8 bytes
    pub merkle_root: [u8; 32],       // 32 bytes - L2 state root
    pub user_xp: u64,                // 8 bytes
    pub user_deadlocks: u64,         // 8 bytes
    pub user_tx_completed: u64,      // 8 bytes
    pub user_tx_disputed: u64,       // 8 bytes
    pub completion_rate: u64,        // 8 bytes (0-100)
    pub amount_sompi: u64,           // 8 bytes
    pub l1_block_height: u64,        // 8 bytes
}

impl WithdrawalInscription {
    pub fn new(
        epoch: u64,
        merkle_root: Fr,
        user_xp: u64,
        user_deadlocks: u64,
        user_tx_completed: u64,
        user_tx_disputed: u64,
        amount_sompi: u64,
        l1_block_height: u64,
    ) -> Self {
        let root_bytes = merkle_root.to_repr();
        let mut root = [0u8; 32];
        root.copy_from_slice(&root_bytes[0..32]);
        
        let total = user_tx_completed + user_tx_disputed;
        let completion_rate = if total > 0 { (user_tx_completed * 100) / total } else { 100 };
        
        Self {
            epoch,
            merkle_root: root,
            user_xp,
            user_deadlocks,
            user_tx_completed,
            user_tx_disputed,
            completion_rate,
            amount_sompi,
            l1_block_height,
        }
    }

    /// Serialize for L1 OP_DATA script (96 bytes)
    pub fn to_inscription_bytes(&self) -> Vec<u8> {
        let mut bytes = Vec::with_capacity(96);
        bytes.extend_from_slice(&self.epoch.to_le_bytes());            // 8
        bytes.extend_from_slice(&self.merkle_root);                    // 32
        bytes.extend_from_slice(&self.user_xp.to_le_bytes());          // 8
        bytes.extend_from_slice(&self.user_deadlocks.to_le_bytes());   // 8
        bytes.extend_from_slice(&self.user_tx_completed.to_le_bytes());// 8
        bytes.extend_from_slice(&self.user_tx_disputed.to_le_bytes()); // 8
        bytes.extend_from_slice(&self.completion_rate.to_le_bytes());  // 8
        bytes.extend_from_slice(&self.amount_sompi.to_le_bytes());     // 8
        bytes.extend_from_slice(&self.l1_block_height.to_le_bytes());  // 8
        bytes // 96 bytes total
    }

    /// Generate OP_DATA script hex for Kaspa (OP_DATA_96 = 0x60)
    pub fn to_script_hex(&self) -> String {
        let payload = self.to_inscription_bytes();
        format!("4c60{}", hex::encode(&payload))
    }

    /// Compute commitment hash for proof verification
    pub fn commitment_hash(&self) -> Fr {
        let constants = PoseidonConstants::<Fr, U8>::new();
        let mut hasher = Poseidon::<Fr, U8>::new(&constants);
        hasher.input(Fr::from(self.epoch)).unwrap();
        let root_fr = Fr::from_repr(self.merkle_root).unwrap_or(Fr::zero());
        hasher.input(root_fr).unwrap();
        hasher.input(Fr::from(self.user_xp)).unwrap();
        hasher.input(Fr::from(self.user_deadlocks)).unwrap();
        hasher.input(Fr::from(self.user_tx_completed)).unwrap();
        hasher.input(Fr::from(self.user_tx_disputed)).unwrap();
        hasher.input(Fr::from(self.amount_sompi)).unwrap();
        hasher.input(Fr::from(self.l1_block_height)).unwrap();
        hasher.hash()
    }
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub enum WithdrawalStatus {
    Pending,           // Awaiting proof
    Proven,            // Proof verified
    L2Verified,        // L2 proof verified
    Executed,          // Executed on L1
    L1Inscribed,       // Inscribed on L1
    Withdrawn,         // User claimed withdrawal
    L1Settled,         // L1 settlement confirmed
    Finalized,         // L1 block confirmed
    Failed(String),    // Failed reason
}

/// Withdrawal ledger – tracks all withdrawals on L2
#[derive(Clone, Debug)]
pub struct WithdrawalLedger {
    pub requests: HashMap<u64, WithdrawalRequestPipeline>,  // request_id → request
    pub spent_nullifiers: BTreeSet<Fq>,  // Changed from HashSet             // Double-spend prevention
    pub next_request_id: u64,
}

impl WithdrawalLedger {
    pub fn new() -> Self {
        Self {
            requests: HashMap::new(),
            spent_nullifiers: BTreeSet::new(),
            next_request_id: 0,
        }
    }
    
    /// Register withdrawal request
    pub fn register_request(
        &mut self,
        account_index: u64,
        amount: u64,
        kaspa_destination: [u8; 34],
        epoch: u64,
    ) -> Result<u64, String> {
        if amount == 0 || amount > CAP_SOMPI {
            return Err("Invalid withdrawal amount".to_string());
        }
        
        let request_id = self.next_request_id;
        self.next_request_id += 1;
        
        self.requests.insert(
            request_id,
            WithdrawalRequestPipeline {
                account_index,
                amount,
                kaspa_destination,
                requested_epoch: epoch,
                status: WithdrawalStatus::Pending,
                inscription: None,
            },
        );
        
        Ok(request_id)
    }

    /// Attach inscription to withdrawal request
    pub fn attach_inscription(
        &mut self,
        request_id: u64,
        inscription: WithdrawalInscription,
    ) -> Result<(), String> {
        if let Some(request) = self.requests.get_mut(&request_id) {
            request.inscription = Some(inscription);
            Ok(())
        } else {
            Err("Request not found".to_string())
        }
    }
    pub fn mark_nullifier_spent(&mut self, nullifier: Fq) -> Result<(), String> {
        if self.is_nullifier_spent_fq(&nullifier) {
            return Err("Nullifier already spent".to_string());
        }
        self.spent_nullifiers.insert(nullifier);
        Ok(())
    }
    
    fn is_nullifier_spent_fq(&self, nullifier: &Fq) -> bool {
        self.spent_nullifiers.contains(nullifier)
    }
    
    /// Update request status
    pub fn update_request_status(
        &mut self,
        request_id: u64,
        status: WithdrawalStatus,
    ) -> Result<(), String> {
        if let Some(request) = self.requests.get_mut(&request_id) {
            request.status = status;
            Ok(())
        } else {
            Err("Request not found".to_string())
        }
    }
    
    /// Get pending withdrawals
    pub fn pending_withdrawals(&self) -> Vec<(u64, WithdrawalRequestPipeline)> {
        self.requests
            .iter()
            .filter(|(_, req)| req.status == WithdrawalStatus::Pending)
            .map(|(id, req)| (*id, req.clone()))
            .collect()
    }
}

// ============================================================================
// WITHDRAWAL PROCESSOR (FULL PIPELINE)
// ============================================================================

/// End-to-end withdrawal processor
pub struct WithdrawalProcessor {
    pub ledger: WithdrawalLedger,
    pub merkle_root: Fr,
    pub account_tree: HashMap<u64, CanonicalAccountLeaf>,
    pub nullifier_set: BTreeSet<Fr>,
}

impl WithdrawalProcessor {
    pub fn new(merkle_root: Fr) -> Self {
        Self {
            ledger: WithdrawalLedger::new(),
            merkle_root,
            account_tree: HashMap::new(),
            nullifier_set: BTreeSet::new(),
        }
    }
    
    /// ✅ STEP 1: Register account in L2 tree
    pub fn register_account(
        &mut self,
        index: u64,
        leaf: CanonicalAccountLeaf,
    ) -> Result<(), String> {
        if self.account_tree.contains_key(&index) {
            return Err("Account already registered".to_string());
        }
        self.account_tree.insert(index, leaf);
        Ok(())
    }
    
    /// ✅ STEP 2: Initiate withdrawal request
    pub fn initiate_withdrawal(
        &mut self,
        account_index: u64,
        amount: u64,
        kaspa_destination: [u8; 34],
        epoch: u64,
    ) -> Result<u64, String> {
        // Verify account exists
        if !self.account_tree.contains_key(&account_index) {
            return Err("Account not found".to_string());
        }
        
        let request_id = self.ledger.register_request(
            account_index,
            amount,
            kaspa_destination,
            epoch,
        )?;
        
        Ok(request_id)
    }
    
    /// ✅ STEP 3: Generate withdrawal proof
    pub fn generate_withdrawal_proof(
        &self,
        request_id: u64,
        account_balance: u64,
        frost_key: Fr,
        frost_commitment: Fr,
        account_leaf_hash: Fr,
    ) -> Result<WithdrawalProofOutput, String> {
        // Get request
        let request = self.ledger.requests
            .get(&request_id)
            .ok_or("Request not found".to_string())?;
        
        // Get account
        let account = self.account_tree
            .get(&request.account_index)
            .ok_or("Account not found".to_string())?;
        
        // Create leaf
        let leaf = WithdrawalLeaf {
            pk: account.kaspa_pubkey.into(),
            amount: request.amount,
            nonce: account.nonce,
            kaspa_dest: request.kaspa_destination,
        };
        
        // Create witness
        let witness = WithdrawalProofWitness::new(
            leaf,
            account_balance,
            self.merkle_root,
            frost_key,
            frost_commitment,
            account_leaf_hash,
        )?;
        
        // Generate proof
        WithdrawalProofGenerator::generate_proof(witness)
    }
    
    /// ✅ STEP 4: Verify and execute withdrawal
    pub fn execute_withdrawal(
        &mut self,
        request_id: u64,
        proof: WithdrawalProofOutput,
    ) -> Result<(), String> {
        // 1. Verify proof
        proof.verify()?;
        let nullifier_fq = FieldConverter::fr_to_fq(proof.nullifier);
        // 2. Check nullifier not spent
        if self.ledger.is_nullifier_spent_fq(&nullifier_fq) {
            return Err("Double-spend detected".to_string());
        }
       
self.ledger.mark_nullifier_spent(nullifier_fq)?;
self.nullifier_set.insert(FieldConverter::fq_to_fr(nullifier_fq));
        
        // 4. Update request status
        self.ledger.update_request_status(
            request_id,
            WithdrawalStatus::Proven,
        )?;
        
        // 5. Update account nonce (prevent replays)
        if let Some(account) = self.account_tree.get_mut(&self.ledger.requests[&request_id].account_index) {
            account.increment_nonce();
        }
        
        Ok(())
    }

    /// ✅ STEP 4b: Execute withdrawal with user stats inscription
    pub fn execute_withdrawal_with_inscription(
        &mut self,
        request_id: u64,
        proof: WithdrawalProofOutput,
        user_xp: u64,
        user_deadlocks: u64,
        user_tx_completed: u64,
        user_tx_disputed: u64,
        l1_block_height: u64,
    ) -> Result<WithdrawalInscription, String> {
        // Execute base withdrawal
        self.execute_withdrawal(request_id, proof)?;
        
        // Get request amount
        let amount = self.ledger.requests
            .get(&request_id)
            .map(|r| r.amount)
            .ok_or("Request not found")?;
        
        // Get current epoch
        let epoch = self.ledger.requests
            .get(&request_id)
            .map(|r| r.requested_epoch)
            .ok_or("Request not found")?;
        
        // Create inscription with user stats
        let inscription = WithdrawalInscription::new(
            epoch,
            self.merkle_root,
            user_xp,
            user_deadlocks,
            user_tx_completed,
            user_tx_disputed,
            amount,
            l1_block_height,
        );
        
        // Attach inscription to request
        self.ledger.attach_inscription(request_id, inscription.clone())?;
        
        // Update status to L1Inscribed
        self.ledger.update_request_status(request_id, WithdrawalStatus::L1Inscribed)?;
        
        Ok(inscription)
    }
    
    /// ✅ STEP 5: Finalize withdrawal (after L1 confirmation)
    pub fn finalize_withdrawal(&mut self, request_id: u64) -> Result<(), String> {
        self.ledger.update_request_status(
            request_id,
            WithdrawalStatus::Finalized,
        )?;
        Ok(())
    }
    
    /// Get withdrawal details
    pub fn get_withdrawal(
        &self,
        request_id: u64,
    ) -> Result<(WithdrawalRequestPipeline, Option<CanonicalAccountLeaf>), String> {
        let request = self.ledger.requests
            .get(&request_id)
            .ok_or("Request not found".to_string())?
            .clone();
        
        let account = self.account_tree.get(&request.account_index).cloned();
        
        Ok((request, account))
    }
}

// ============================================================================
// BATCH WITHDRAWAL PROCESSING (FOR ROLLUPS)
// ============================================================================

/// Process multiple withdrawals atomically
pub struct BatchWithdrawalProcessor {
    pub withdrawals: Vec<(u64, WithdrawalProofOutput)>, // request_id → proof
    pub processor: WithdrawalProcessor,
}

impl BatchWithdrawalProcessor {
    pub fn new(processor: WithdrawalProcessor) -> Self {
        Self {
            withdrawals: vec![],
            processor,
        }
    }
    
    /// Add withdrawal to batch
    pub fn add_withdrawal(
        &mut self,
        request_id: u64,
        proof: WithdrawalProofOutput,
    ) -> Result<(), String> {
        // Quick verify
        proof.verify()?;
        
        // Check bounds
        if proof.amount > CAP_SOMPI {
            return Err("Exceeds cap".to_string());
        }
        
        self.withdrawals.push((request_id, proof));
        Ok(())
    }
    
    /// Execute all withdrawals atomically
    pub fn execute_batch(&mut self) -> Result<Vec<u64>, Vec<(u64, String)>> {
        let mut succeeded = Vec::new();
        let mut failed = Vec::new();
        
        for (request_id, proof) in self.withdrawals.clone() {
            match self.processor.execute_withdrawal(request_id, proof) {
                Ok(()) => succeeded.push(request_id),
                Err(e) => failed.push((request_id, e)),
            }
        }
        
        if failed.is_empty() {
            Ok(succeeded)
        } else {
            Err(failed)
        }
    }
    
    /// Compute batch root for L1 posting
    pub fn compute_batch_root(&self) -> Fr {
        let nullifiers: Vec<Fr> = self.withdrawals
            .iter()
            .map(|(_, proof)| proof.nullifier)
            .collect();
        
        let constants = PoseidonConstants::<Fr, U8>::new();
        let mut hasher = Poseidon::<Fr, U8>::new(&constants);
        
        hasher.input(Fr::from(D_COMMIT1)).unwrap();
        for nullifier in &nullifiers {
            hasher.input(*nullifier).unwrap();
        }
        
        // Pad to fixed arity
        for _ in nullifiers.len()..7 {
            hasher.input(Fr::zero()).unwrap();
        }
        
        hasher.hash()
    }
}

// ============================================================================
// WITHDRAWAL PROOF WITH MERKLE TREE
// ============================================================================

/// Withdrawal proof extended with Merkle path verification
#[derive(Clone, Debug)]
pub struct WithdrawalProofWithMerkle {
    pub proof: WithdrawalProofOutput,
    pub merkle_path: Vec<(Fr, bool)>,  // Merkle proof path
    pub merkle_root: Fr,
}

impl WithdrawalProofWithMerkle {
    /// Verify withdrawal with Merkle inclusion proof
    pub fn verify_with_merkle(&self, account_leaf_hash: Fr) -> Result<(), String> {
        // 1. Verify withdrawal proof
        self.proof.verify()?;
        
        // 2. Verify Merkle inclusion
        let mut current = account_leaf_hash;
        for (sibling, is_left) in &self.merkle_path {
            current = if *is_left {
                internal_hash_fr(*sibling, current)
            } else {
                internal_hash_fr(current, *sibling)
            };
        }
        
        // 3. Check computed root matches
        if current != self.merkle_root {
            return Err("Merkle root mismatch".to_string());
        }
        
        Ok(())
    }
}

