/// API response: success
#[derive(Clone, Debug, Serialize)]
pub struct ApiResponse<T: Serialize> {
    pub success: bool,
    pub data: Option<T>,
    pub error: Option<String>,
}

impl<T: Serialize> ApiResponse<T> {
    pub fn ok(data: T) -> Self {
        Self {
            success: true,
            data: Some(data),
            error: None,
        }
    }

    pub fn err(msg: String) -> ApiResponse<()> {
        ApiResponse {
            success: false,
            data: None,
            error: Some(msg),
        }
    }
}

/// Server state (shared across handlers)
pub struct ServerState {
    pub halo2_setup: Arc<Halo2Setup>,
    pub proof_generator: Arc<ProofGenerator>,
    pub kaspa_submitter: Arc<KaspaRootSubmitter>,
    pub ledger: Arc<RwLock<NonCustodialLedger>>,
}

// ============================================================================
// API ROUTING MAP - WHICH ENDPOINT GOES WHERE ON NETWORK
// ============================================================================
//
// Network Architecture:
//   [Fastly CDN] → [Cloudflare] → [AWS Primary] ↔ [Akash Secondary] → [Kaspa L1]
//
// API Endpoint Routing:
//
// 🟢 AWS PRIMARY NODE (all mutation/read operations)
// ├─ POST /api/deposit
// │  └─ Service: L2ClientSDK + Irmin database
// │     Action: Store deposit in Merkle tree, update balances
// │     Response: deposit_commitment, amount, timestamp
// │
// ├─ POST /api/withdrawal
// │  └─ Service: L2ClientSDK + Irmin database
// │     Action: Validate withdrawal, check nonce, generate nullifier
// │     Response: withdrawal_hash, amount, nonce
// │
// ├─ POST /api/proof
// │  └─ Service: Halo2Setup + ProofGenerator
// │     Action: Generate ZK proof for withdrawal (expensive!)
// │     Input: withdrawal + merkle_path + root (from Irmin tree)
// │     Response: proof bytes (Halo2), withdrawal_hash
// │
// ├─ GET /api/state
// │  └─ Service: NonCustodialLedger (read-only)
// │     Action: Query current L2 state
// │     Response: version, merkle_root, total_balance
// │
// ├─ POST /api/submit-root
// │  └─ Service: KaspaRootSubmitter + kas.fyi API
// │     Action: Publish L2 root to Kaspa L1 (OP_DATA, 32 bytes)
// │     Input: sender (AWS address), root (Fr), epoch (u32)
// │     Response: txid on Kaspa
// │     Destination: Kaspa L1 blockchain
// │
// ├─ POST /api/sync/replicate ⭐
// │  └─ Service: StateReplicator
// │     Action: Create StateSnapshot from Irmin tree, send to Akash
// │     Triggers: background task (every 30s) or manual
// │     Payload: merkle_root, epoch, tree_hash, ledger_version
// │
// └─ POST /api/sync/verify
//    └─ Service: StateReplicator
//       Action: Compare AWS vs Akash merkle roots
//       Response: in_sync (bool), primary_state, secondary_state
//
// 🟦 AKASH SECONDARY NODE (failover + read mirror)
// ├─ POST /api/sync/state
// │  └─ Service: StateReplicator (receives from AWS)
// │     Action: Accept snapshot, update local Irmin mirror
// │     Input: StateSnapshot from AWS
// │     Response: success, epoch, merkle_root
// │
// ├─ POST /api/sync/promote ⭐
// │  └─ Service: Failover controller
// │     Action: Promote Akash to primary (if AWS down)
// │     Condition: Only if in_sync == true
// │     Response: promoted_to: "primary", epoch, timestamp
// │     Effect: AWS still owns Merkle tree (cached), Akash takes requests
// │
// ├─ GET /api/state (read-only mirror)
// │  └─ Service: Mirror NonCustodialLedger (copied from AWS)
// │     Action: Serve cached L2 state
// │     Response: same as AWS (stale up to sync interval)
// │
// └─ (Supports deposit/withdrawal endpoints as fallback during AWS failure)
//
// 💚 KASPA L1 (settlement layer - written via AWS)
// └─ Merkle Root Storage (OP_DATA script, 32 bytes)
//    Source: AWS submits via KaspaRootSubmitter (kas.fyi API)
//    Format: [28 bytes root hash | 4 bytes epoch]
//    Permanence: Immutable once confirmed
//    Role: Trust anchor for all L2 state proofs
//
// 🔐 IRMIN DATABASE (Merkle tree state storage)
// ├─ Location: AWS primary (canonical), Akash secondary (mirror)
// ├─ Structure: Merkle tree with leaf hashes
// ├─ Stored: balances, transactions, nullifiers, nonces
// ├─ Operations:
// │  ├─ /api/deposit → INSERT leaf (hash of user+amount+nonce)
// │  ├─ /api/withdrawal → MARK nullifier (prevent double-spend)
// │  ├─ /api/proof → GENERATE merkle_path from root to leaf
// │  └─ /api/sync/replicate → SNAPSHOT entire tree (root + epoch)
// └─ Kaspa stores ONLY root (32 bytes), full tree off-chain
//
// 🟡 CLOUDFLARE (routing layer)
// └─ Routes incoming requests:
//    ├─ Normal: → AWS (primary)
//    └─ AWS down: → Akash (secondary)
//    All endpoints maintain same API contract
//
// 🔵 FASTLY CDN (static distribution)
// └─ Serves (read-only):
//    ├─ L2 client app (JS/WASM)
//    ├─ Merkle proofs (static cache)
//    ├─ Public keys
//    └─ UI assets
//
// FLOW EXAMPLE: User Withdraws 100 KAS
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// 1. User → Fastly/Cloudflare → AWS
// 2. POST /api/withdrawal → L2ClientSDK validates
// 3. AWS queries Irmin: get user's merkle_path in tree
// 4. POST /api/proof → ProofGenerator creates Halo2 proof
// 5. Proof sent back to user (or to server for submission)
// 6. POST /api/submit-root → KaspaRootSubmitter sends root to Kaspa L1
// 7. Background task: /api/sync/replicate → sends snapshot to Akash
// 8. Akash: POST /api/sync/state → stores mirror copy
// 9. GET /api/sync/verify → confirms both in_sync
//
// If AWS fails (step 6):
// ├─ Cloudflare redirects to Akash
// ├─ Akash promotes via POST /api/sync/promote
// ├─ Akash now handles requests (from cached state)
// ├─ Kaspa L1 holds last confirmed root (immutable)
// └─ Users can prove withdrawals against that root
//

// ============================================================================
// API ENDPOINT HANDLERS
// ============================================================================

/// POST /api/deposit - Submit deposit request
/// SERVICE: AWS Primary (Irmin database)
/// ROLE: Insert deposit into Merkle tree, update balances
async fn handle_deposit(
    state: web::Data<ServerState>,
    req: web::Json<ApiDepositRequest>,
) -> impl Responder {
    // Parse addresses
    let kaspa_addr = match parse_kaspa_address(&req.kaspa_address) {
        Ok(a) => a,
        Err(e) => return HttpResponse::BadRequest().json(ApiResponse::<()>::err(e)),
    };

    // Create deposit
    let deposit = match DepositRequest::new(kaspa_addr, req.amount_sompi) {
        Ok(d) => d,
        Err(e) => return HttpResponse::BadRequest().json(ApiResponse::<()>::err(e)),
    };

    // Update ledger
    {
        let mut ledger = state.ledger.write().await;
        ledger.apply_update(Fr::from(deposit.amount_sompi), Fr::zero());
    }

    let response = serde_json::json!({
        "deposit_commitment": format!("{:?}", deposit.compute_commitment()),
        "amount": deposit.amount_sompi,
        "timestamp": deposit.timestamp,
    });

    HttpResponse::Ok().json(ApiResponse::ok(response))
}

/// POST /api/withdrawal - Submit withdrawal request
/// SERVICE: AWS Primary (L2ClientSDK + Irmin)
/// ROLE: Validate withdrawal, check balance, increment nonce
/// SECURITY: Requires hardware wallet signature proof, blocks exchange addresses
async fn handle_withdrawal(
    state: web::Data<ServerState>,
    req: web::Json<ApiWithdrawalRequest>,
) -> impl Responder {
    // SECURITY CHECK 1: Require signature proof
    let signature_proof = match &req.signature_proof {
        Some(proof) => proof,
        None => return HttpResponse::BadRequest().json(ApiResponse::<()>::err(
            "Withdrawal requires signature proof from hardware wallet (Ledger, Tangem, OneKey, or Kaspium). Direct address entry is not permitted.".to_string()
        )),
    };
    
    // SECURITY CHECK 2: Verify the signature proof
    if let Err(e) = verify_signature_proof(signature_proof, &req.kaspa_destination) {
        return HttpResponse::BadRequest().json(ApiResponse::<()>::err(
            format!("Signature verification failed: {}. Please re-connect your hardware wallet.", e)
        ));
    }
    
    // SECURITY CHECK 3: Block exchange addresses
    if is_exchange_address(&req.kaspa_destination) {
        return HttpResponse::BadRequest().json(ApiResponse::<()>::err(
            "Direct withdrawals to exchange addresses are NOT permitted. Please withdraw to your verified self-custody wallet first, then send to exchanges manually.".to_string()
        ));
    }
    
    // Parse addresses
    let pubkey = match parse_pubkey(&req.user_pubkey) {
        Ok(p) => p,
        Err(e) => return HttpResponse::BadRequest().json(ApiResponse::<()>::err(e)),
    };

    let kaspa_dest = match parse_kaspa_address(&req.kaspa_destination) {
        Ok(a) => a,
        Err(e) => return HttpResponse::BadRequest().json(ApiResponse::<()>::err(e)),
    };

    // Create withdrawal (kaspa_dest stored separately for L1 settlement)
    let withdrawal = match WithdrawalRequest::new(pubkey, req.amount_sompi) {
        Ok(w) => w,
        Err(e) => return HttpResponse::BadRequest().json(ApiResponse::<()>::err(e.to_string())),
    };

    let response = serde_json::json!({
        "success": true,
        "withdrawal_hash": format!("{:?}", withdrawal.hash()),
        "amount": withdrawal.amount,
        "kaspa_destination": req.kaspa_destination,
        "verified_wallet_type": signature_proof.wallet_type,
        "signature_verified": true,
    });

    HttpResponse::Ok().json(ApiResponse::ok(response))
}

/// POST /api/proof - Generate withdrawal proof
/// SERVICE: AWS Primary (Halo2Setup + ProofGenerator - EXPENSIVE)
/// ROLE: Generate ZK proof from merkle_path + root (heavy computation)
async fn handle_proof(
    state: web::Data<ServerState>,
    req: web::Json<ApiProofRequest>,
) -> impl Responder {
    // Parse inputs
    let pubkey = match parse_pubkey(&req.withdrawal.user_pubkey) {
        Ok(p) => p,
        Err(e) => return HttpResponse::BadRequest().json(ApiResponse::<()>::err(e)),
    };

    let kaspa_dest = match parse_kaspa_address(&req.withdrawal.kaspa_destination) {
        Ok(a) => a,
        Err(e) => return HttpResponse::BadRequest().json(ApiResponse::<()>::err(e)),
    };

    let withdrawal = match WithdrawalRequest::new(pubkey, req.withdrawal.amount_sompi) {
        Ok(w) => w,
        Err(e) => return HttpResponse::BadRequest().json(ApiResponse::<()>::err(e.to_string())),
    };

    let merkle_path: Result<Vec<Fr>, String> = req.merkle_path
        .iter()
        .map(|h| parse_field_element_fr(h))
        .collect();

    let merkle_path = match merkle_path {
        Ok(p) => p,
        Err(e) => return HttpResponse::BadRequest().json(ApiResponse::<()>::err(e)),
    };

    let root = match parse_field_element_fr(&req.merkle_root) {
        Ok(r) => r,
        Err(_) => return HttpResponse::BadRequest().json(ApiResponse::<()>::err("Invalid root".to_string())),
    };

    // Generate proof
    let proof = match state.proof_generator
        .generate_withdrawal_proof(&withdrawal, &merkle_path, root)
        .await {
        Ok(p) => p,
        Err(e) => return HttpResponse::InternalServerError().json(ApiResponse::<()>::err(e)),
    };

    let response = serde_json::json!({
        "proof": hex::encode(proof),
        "withdrawal_hash": format!("{:?}", withdrawal.hash()),
    });

    HttpResponse::Ok().json(ApiResponse::ok(response))
}

/// GET /api/state - Query current L2 state
/// SERVICE: AWS Primary OR Akash Secondary (read-only mirror)
/// ROLE: Return merkle_root, version
async fn handle_state(state: web::Data<ServerState>) -> impl Responder {
    let ledger = state.ledger.read().await;

    let response = serde_json::json!({
        "version": ledger.version,
        "merkle_root": format!("{:?}", ledger.merkle_root),
        "state_commitment": format!("{:?}", ledger.state_commitment),
    });

    HttpResponse::Ok().json(ApiResponse::ok(response))
}

/// POST /api/submit-root - Submit L2 root to Kaspa L1
/// SERVICE: AWS Primary → KaspaRootSubmitter → kas.fyi API → Kaspa blockchain
/// ROLE: Inscribe merkle_root as OP_DATA on L1 (32 bytes: root + epoch)
/// DESTINATION: Kaspa L1 (immutable settlement)
async fn handle_submit_root(
    state: web::Data<ServerState>,
    req: web::Json<serde_json::Value>,
) -> impl Responder {
    let sender = match req.get("sender").and_then(|v| v.as_str()) {
        Some(s) => s.to_string(),
        None => return HttpResponse::BadRequest().json(ApiResponse::<()>::err("Missing sender".to_string())),
    };

    let root_str = match req.get("root").and_then(|v| v.as_str()) {
        Some(r) => r,
        None => return HttpResponse::BadRequest().json(ApiResponse::<()>::err("Missing root".to_string())),
    };

    let root = match parse_field_element_fr(root_str) {
        Ok(r) => r,
        Err(_) => return HttpResponse::BadRequest().json(ApiResponse::<()>::err("Invalid root".to_string())),
    };

    let epoch = req.get("epoch")
        .and_then(|v| v.as_u64())
        .unwrap_or(0) as u32;

    // Submit to Kaspa L1
    let txid = match state.kaspa_submitter.submit_root_blocking(sender, root, epoch) {
        Ok(id) => id,
        Err(e) => return HttpResponse::InternalServerError().json(ApiResponse::<()>::err(e)),
    };

    let response = serde_json::json!({
        "txid": txid,
        "root": root_str,
        "epoch": epoch,
    });

    HttpResponse::Ok().json(ApiResponse::ok(response))
}

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

fn parse_kaspa_address(addr: &str) -> Result<[u8; 34], String> {
    if addr.len() != 68 {
        return Err("Invalid address length".to_string());
    }

    let bytes = hex::decode(addr)
        .map_err(|_| "Invalid hex".to_string())?;

    if bytes.len() != 34 {
        return Err("Invalid address size".to_string());
    }

    let mut result = [0u8; 34];
    result.copy_from_slice(&bytes);
    Ok(result)
}

fn parse_pubkey(pubkey: &str) -> Result<[u8; 33], String> {
    if pubkey.len() != 66 {
        return Err("Invalid pubkey length".to_string());
    }

    let bytes = hex::decode(pubkey)
        .map_err(|_| "Invalid hex".to_string())?;

    if bytes.len() != 33 {
        return Err("Invalid pubkey size".to_string());
    }

    let mut result = [0u8; 33];
    result.copy_from_slice(&bytes);
    Ok(result)
}

/// Parse hex string to Fr field element
fn parse_field_element_fr(hex_str: &str) -> Result<Fr, String> {
    let hex_str = hex_str.strip_prefix("0x").unwrap_or(hex_str);
    let bytes = hex::decode(hex_str)
        .map_err(|_| "Invalid hex".to_string())?;
    
    if bytes.len() != 32 {
        return Err(format!("Expected 32 bytes, got {}", bytes.len()));
    }
    
    let mut repr = [0u8; 32];
    repr.copy_from_slice(&bytes);
    
    Option::from(Fr::from_repr(repr))
        .ok_or_else(|| "Invalid field element".to_string())
}

// ============================================================================
// SERVER STARTUP
// ============================================================================

/// Start Actix-web server with API endpoints
pub async fn start_api_server(
    host: &str,
    port: u16,
) -> Result<(), Box<dyn std::error::Error>> {
    println!("🚀 Starting KasVillage L2 Server...");
    
    // ========================================================================
    // CORE CRYPTOGRAPHIC SETUP
    // ========================================================================
    let halo2_setup = Arc::new(Halo2Setup::new()?);
    let proof_generator = Arc::new(ProofGenerator::new(halo2_setup.clone()));
    let kaspa_submitter = Arc::new(KaspaRootSubmitter::mainnet());
    let ledger = Arc::new(RwLock::new(NonCustodialLedger::new()));

    // ========================================================================
    // KASPA L1 NODE - Self-hosted (Flux) or public API
    // ========================================================================
    // Configure via: KASPA_NODE_URL=ws://your-flux-node:16210
    // Or use public API if not set
    let kaspa_node = Arc::new(KaspaFluxNode::from_env());
    
    // Health check the node
    match kaspa_node.health_check().await {
        Ok(true) => println!("[KASPA] ✓ Node connected: {}", kaspa_node.node_url()),
        Ok(false) => eprintln!("[KASPA] ⚠ Node returned unhealthy"),
        Err(e) => eprintln!("[KASPA] ⚠ Node health check failed: {}", e),
    }
    
    let kaspa_node_data = web::Data::new(kaspa_node.clone());

    let state = web::Data::new(ServerState {
        halo2_setup: halo2_setup.clone(),
        proof_generator: proof_generator.clone(),
        kaspa_submitter,
        ledger,
    });

    // ========================================================================
    // MERKLE TREES - One main tree, one sanctions tree
    // ========================================================================
    let main_tree = Arc::new(std::sync::RwLock::new(SparseMerkleTree::new(TREE_DEPTH)));
    let sanctions_tree = Arc::new(std::sync::RwLock::new(SparseMerkleTree::new(TREE_DEPTH)));
    
    let main_tree_data = web::Data::new(main_tree.clone());
    let sanctions_tree_data = web::Data::new(sanctions_tree.clone());
    
    println!("[MERKLE] ✓ Main tree initialized (depth {})", TREE_DEPTH);
    println!("[MERKLE] ✓ Sanctions tree initialized (depth {})", TREE_DEPTH);

    // ========================================================================
    // SANCTIONS - Load Treasury OFAC + OpenSanctions
    // ========================================================================
    println!("[SANCTIONS] Loading sanctions lists...");
    
    let sanctions_db = match fetch_ofac_sdn_list().await {
        Ok(mut db) => {
            println!("[SANCTIONS] ✓ Treasury OFAC: {} entries, {} crypto addresses", 
                db.entry_count, db.sdn_addresses.len());
            
            match ComplianceSanctionsLoader::load_opensanctions_csv().await {
                Ok(opensanctions) => {
                    let addr_before = db.sdn_addresses.len();
                    let name_before = db.sdn_names.len();
                    
                    for source in opensanctions {
                        let id = source.identifier.trim();
                        if id.starts_with("0x") && id.len() == 42 {
                            db.sdn_addresses.insert(id.to_lowercase());
                        } else if id.starts_with("kaspa:") && id.len() >= 60 {
                            db.sdn_addresses.insert(id.to_string());
                        } else if (id.starts_with("1") || id.starts_with("3") || id.starts_with("bc1")) 
                            && id.len() >= 26 && id.len() <= 62 {
                            db.sdn_addresses.insert(id.to_string());
                        } else if id.len() > 2 {
                            db.sdn_names.insert(id.to_uppercase());
                        }
                    }
                    
                    println!("[SANCTIONS] ✓ OpenSanctions: +{} addresses, +{} names", 
                        db.sdn_addresses.len() - addr_before,
                        db.sdn_names.len() - name_before);
                }
                Err(e) => eprintln!("[SANCTIONS] ⚠ OpenSanctions load failed: {}", e),
            }
            
            println!("[SANCTIONS] ✓ Total: {} addresses, {} names, {} countries",
                db.sdn_addresses.len(), db.sdn_names.len(), db.sdn_countries.len());
            db
        }
        Err(e) => {
            eprintln!("[SANCTIONS] ⚠ Treasury OFAC load failed: {}", e);
            SanctionsDatabase::default()
        }
    };
    
    let sanctions_state = web::Data::new(SanctionsState {
        db: Arc::new(RwLock::new(sanctions_db)),
    });
    
    let sanctions_db_ref = sanctions_state.db.clone();
    tokio::spawn(async move {
        sanctions_refresh_task(sanctions_db_ref).await;
    });

    // ========================================================================
    // APP STATE - Storefronts, Consignments, Onboarding, Stats
    // ========================================================================
    let app_state = web::Data::new(AppStateAdditions {
        circuit_breaker: RwLock::new(CircuitBreakerState::new()),
        consignment_agreements: RwLock::new(HashMap::new()),
        storefronts: RwLock::new(HashMap::new()),
        storefront_visits: RwLock::new(HashMap::new()),
        storefront_click_counts: RwLock::new(HashMap::new()),
        merchant_balances: RwLock::new(HashMap::new()),
        onboarding_sessions: RwLock::new(HashMap::new()),
        onboarding_scores: RwLock::new(HashMap::new()),
        sanctions: SanctionsState::new(),
    });

    // ========================================================================
    // IDENTITY MERKLE TREE - Avatar commitments (ZK-Identity)
    // ========================================================================
    let identity_tree = web::Data::new(std::sync::RwLock::new(IdentityMerkleTree::new()));
    println!("[IDENTITY] ✓ Identity tree initialized");

    // ========================================================================
    // UNIFIED ACCOUNT REGISTRY - Maps pubkey to all account data
    // ========================================================================
    let account_registry = web::Data::new(std::sync::RwLock::new(UnifiedAccountRegistry::new()));
    println!("[ACCOUNTS] ✓ Unified account registry initialized");

    // ========================================================================
    // QUANTUM MERKLE TREE - Ephemeral signatures for offline transactions
    // ========================================================================
    let qr_tree = web::Data::new(std::sync::RwLock::new(QuantumMerkleTree::new(QR_MERKLE_DEPTH)));
    println!("[QR-MERKLE] ✓ Quantum-resistant ephemeral key tree initialized (depth {})", QR_MERKLE_DEPTH);

    // ========================================================================
    // AUTONOMOUS PROOF GENERATION
    // ========================================================================
    let proof_gen_clone = proof_generator.clone();
    let main_tree_clone = main_tree.clone();
    tokio::spawn(async move {
        let mut interval = tokio::time::interval(std::time::Duration::from_secs(60));
        loop {
            interval.tick().await;
            let tree = main_tree_clone.read().unwrap();
            let root = tree.root();
            drop(tree);
            println!("[PROOFS] Merkle root: 0x{}", &hex::encode(root.to_repr())[..16]);
        }
    });

    println!("[PROOFS] ✓ Autonomous proof generation started");
    println!("📡 Listening on {}:{}", host, port);

    // ========================================================================
    // HTTP SERVER
    // ========================================================================
    HttpServer::new(move || {
        App::new()
            .app_data(state.clone())
            .app_data(sanctions_state.clone())
            .app_data(app_state.clone())
            .app_data(main_tree_data.clone())
            .app_data(sanctions_tree_data.clone())
            .app_data(identity_tree.clone())
            .app_data(account_registry.clone())
            .app_data(qr_tree.clone())
            .app_data(kaspa_node_data.clone())
            .wrap(Logger::default())
            .wrap(
                Cors::default()
                    .allow_any_origin()
                    .allow_any_method()
                    .allow_any_header()
                    .max_age(3600)
            )
            // Health & State
            .route("/api/health", web::get().to(api_health_full))
            .route("/api/state", web::get().to(handle_state))
            // Core L2 operations
            .route("/api/deposit", web::post().to(handle_deposit))
            .route("/api/withdrawal", web::post().to(handle_withdrawal))
            .route("/api/proof", web::post().to(handle_proof))
            .route("/api/submit-root", web::post().to(handle_submit_root))
            // Merkle proofs
            .route("/api/merkle/proof/{index}", web::get().to(api_merkle_proof))
            .route("/api/merkle/root", web::get().to(api_merkle_root))
            .route("/api/merkle/verify", web::post().to(api_merkle_verify))
            // Identity & Registration
            .route("/api/register", web::post().to(api_register_unified))
            .route("/api/identity/commit", web::post().to(api_identity_commit))
            .route("/api/identity/verify", web::post().to(api_identity_verify))
            .route("/api/identity/questions/{pubkey}", web::get().to(api_get_avatar_questions))
            .route("/api/account/{pubkey}", web::get().to(api_get_account))
            // User endpoints
            .route("/api/user/fcm-token", web::post().to(handle_fcm_register))
            .route("/api/user/fcm-token", web::delete().to(handle_fcm_unregister))
            .route("/api/user/{pubkey}/queue-position", web::get().to(handle_queue_position))
            .route("/api/alerts/active", web::get().to(handle_active_alerts))
            // Kaspa L1 operations
            .route("/api/l1/balance/{address}", web::get().to(api_l1_balance))
            .route("/api/l1/utxos/{address}", web::get().to(api_l1_utxos))
            .route("/api/l1/tx/{hash}", web::get().to(api_l1_transaction))
            .route("/api/l1/blockdag", web::get().to(api_l1_blockdag))
            .route("/api/l1/submit", web::post().to(api_l1_submit_tx))
            // Ephemeral signature routes (QR-Merkle)
            .configure(configure_qr_merkle_routes)
            // All frontend routes
            .configure(configure_routes_additions)
    })
    .bind(&format!("{}:{}", host, port))?
    .run()
    .await?;

    Ok(())
}

