#[derive(Debug, Serialize, Deserialize)]
pub struct SanctionsHandshakeRequest {
    pub pubkey: String,
    pub country_code: Option<String>,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct SanctionsHandshakeResponse {
    pub is_sanctioned: bool,
    pub pubkey: String,
    pub reason: Option<String>,
    pub blocked_country: Option<String>,
    pub last_updated: u64,
    pub checked_at: u64,
}

/// POST /api/sanctions/handshake - Pre-flight sanctions check
/// Returns whether address/country is sanctioned BEFORE any transaction
pub async fn api_sanctions_handshake(
    req: web::Json<SanctionsHandshakeRequest>,
    state: web::Data<FrontendAppState>,
) -> impl Responder {
    let sanctions_db = state.sanctions_state.read().await;
    let checked_at = current_timestamp();

    // 1. Check address first (highest priority)
    if sanctions_db.sdn_addresses.contains(&req.pubkey.to_lowercase()) {
        return HttpResponse::Ok().json(SanctionsHandshakeResponse {
            is_sanctioned: true,
            pubkey: req.pubkey.clone(),
            reason: Some("Address on OFAC SDN list".to_string()),
            blocked_country: None,
            last_updated: sanctions_db.last_updated,
            checked_at,
        });
    }

    // 2. Check country if provided
    if let Some(country) = &req.country_code {
        if sanctions_db.sdn_countries.contains(country) {
            return HttpResponse::Ok().json(SanctionsHandshakeResponse {
                is_sanctioned: true,
                pubkey: req.pubkey.clone(),
                reason: Some(format!("Country sanctioned: {}", country)),
                blocked_country: Some(country.clone()),
                last_updated: sanctions_db.last_updated,
                checked_at,
            });
        }
    }

    // 3. Not sanctioned
    HttpResponse::Ok().json(SanctionsHandshakeResponse {
        is_sanctioned: false,
        pubkey: req.pubkey.clone(),
        reason: None,
        blocked_country: None,
        last_updated: sanctions_db.last_updated,
        checked_at,
    })
}

pub async fn api_health(state: web::Data<FrontendAppState>) -> impl Responder {
    let mut inner = state.inner.write().await;
    inner.circuit_breaker.check_cooldown();
    
    let response = HealthResponse {
        health_level: inner.circuit_breaker.health_level().to_string(),
        is_tripped: inner.circuit_breaker.is_tripped,
        total_outflow_last_hour: inner.circuit_breaker.total_outflow_last_hour,
        threshold: inner.circuit_breaker.threshold,
        cooldown_remaining: if let Some(trip_time) = inner.circuit_breaker.last_trip_time {
            let elapsed = current_timestamp().saturating_sub(trip_time);
            inner.circuit_breaker.cooldown_seconds.saturating_sub(elapsed)
        } else {
            0
        },
    };
    
    HttpResponse::Ok().json(response)
}

/// POST /api/register - User registration
pub async fn api_register(
    state: web::Data<FrontendAppState>,
    req: web::Json<SimpleRegisterRequest>,
) -> impl Responder {
    let mut inner = state.inner.write().await;
    
    // Validate pubkey format
    if req.pubkey.len() != 66 {
        return HttpResponse::BadRequest().json(serde_json::json!({
            "success": false,
            "error": "Invalid pubkey length"
        }));
    }
    
    let user_id = current_timestamp() ^ (inner.users.len() as u64);
    let tier = XPTierV2::from_xp(0);
    
    let user = FrontendUser {
        pubkey: req.pubkey.clone(),
        user_id,
        xp: 0,
        tier: tier.name().to_string(),
        balance_sompi: 0,
        available_balance_sompi: 0,
        locked_withdrawal_sompi: 0,
        subscription_expires_at: None,
        registered_at: current_timestamp(),
    };
    
    inner.users.insert(req.pubkey.clone(), user);
    
    HttpResponse::Ok().json(RegisterResponse {
        success: true,
        token: format!("jwt_{}_{}", user_id, current_timestamp()),
        user_id,
        xp: 0,
        tier: tier.name().to_string(),
    })
}

/// POST /api/apartment/search - Search by apartment code
pub async fn api_apartment_search(
    state: web::Data<FrontendAppState>,
    req: web::Json<ApartmentSearchRequest>,
) -> impl Responder {
    let inner = state.inner.read().await;
    
    // Search for user with matching apt code pattern
    let apt_code = req.apt_code.to_uppercase();
    if apt_code.len() < 3 || !apt_code.chars().all(|c| c.is_alphanumeric()) {
        return HttpResponse::Ok().json(ApartmentSearchResponse {
            found: false,
            pubkey: None,
            display_name: None,
            xp: None,
            tier: None,
        });
    }
    
    // Mock: find user whose pubkey contains apt code
    for (pubkey, user) in &inner.users {
        if pubkey.contains(&apt_code.to_lowercase()) {
            return HttpResponse::Ok().json(ApartmentSearchResponse {
                found: true,
                pubkey: Some(pubkey.clone()),
                display_name: Some(format!("Apt {}", apt_code)),
                xp: Some(user.xp),
                tier: Some(user.tier.clone()),
            });
        }
    }
    
    // Generate mock response for demo
    HttpResponse::Ok().json(ApartmentSearchResponse {
        found: true,
        pubkey: Some(format!("02apt{}pubkey{}", apt_code.to_lowercase(), "0".repeat(40))),
        display_name: Some(format!("Apt {}", apt_code)),
        xp: Some(100),
        tier: Some("Promoter".to_string()),
    })
}

/// POST /api/withdrawal/submit - Submit withdrawal with 24h timelock
/// SECURITY: Requires hardware wallet signature proof, blocks exchange addresses
pub async fn api_withdrawal_submit(
    state: web::Data<FrontendAppState>,
    req: web::Json<WithdrawalSubmitRequest>,
) -> impl Responder {
    // ==========================================================================
    // SECURITY CHECK 0: Check if user/destination is sanctioned
    // ==========================================================================
    {
        let sanctions_db = state.sanctions_state.read().await;
        
        // Block sanctioned user from withdrawing
        if sanctions_db.sdn_addresses.contains(&req.user_pubkey.to_lowercase()) {
            return HttpResponse::Forbidden().json(WithdrawalSubmitResponse {
                success: false,
                request_id: 0,
                submitted_at: 0,
                unlocks_at: 0,
                l1_block_submitted: 0,
                seconds_remaining: 0,
                error: Some("Withdrawal blocked: User address is on sanctions list".to_string()),
            });
        }
        
        // Block withdrawal to sanctioned address
        if sanctions_db.sdn_addresses.contains(&req.dest_address.to_lowercase()) {
            return HttpResponse::Forbidden().json(WithdrawalSubmitResponse {
                success: false,
                request_id: 0,
                submitted_at: 0,
                unlocks_at: 0,
                l1_block_submitted: 0,
                seconds_remaining: 0,
                error: Some("Withdrawal blocked: Destination address is on sanctions list".to_string()),
            });
        }
    }

    // ==========================================================================
    // SECURITY CHECK 1: Require hardware wallet signature proof
    // ==========================================================================
    let signature_proof = match &req.signature_proof {
        Some(proof) => proof,
        None => {
            return HttpResponse::BadRequest().json(WithdrawalSubmitResponse {
                success: false,
                request_id: 0,
                submitted_at: 0,
                unlocks_at: 0,
                l1_block_submitted: 0,
                seconds_remaining: 0,
                error: Some("Withdrawal requires signature proof from hardware wallet (Ledger, Tangem, OneKey, or Kaspium). Direct address entry is not permitted for regulatory compliance.".to_string()),
            });
        }
    };
    
    // ==========================================================================
    // SECURITY CHECK 2: Verify the signature proof is valid
    // ==========================================================================
    if let Err(e) = verify_signature_proof(signature_proof, &req.dest_address) {
        return HttpResponse::BadRequest().json(WithdrawalSubmitResponse {
            success: false,
            request_id: 0,
            submitted_at: 0,
            unlocks_at: 0,
            l1_block_submitted: 0,
            seconds_remaining: 0,
            error: Some(format!("Signature verification failed: {}. Please reconnect your hardware wallet and try again.", e)),
        });
    }
    
    // ==========================================================================
    // SECURITY CHECK 3: Block exchange addresses (regulatory compliance)
    // ==========================================================================
    if is_exchange_address(&req.dest_address) {
        return HttpResponse::BadRequest().json(WithdrawalSubmitResponse {
            success: false,
            request_id: 0,
            submitted_at: 0,
            unlocks_at: 0,
            l1_block_submitted: 0,
            seconds_remaining: 0,
            error: Some("Direct withdrawals to exchange addresses are NOT permitted. Please withdraw to your verified self-custody hardware wallet first, then manually send to exchanges if needed.".to_string()),
        });
    }
    
    let mut inner = state.inner.write().await;
    
    // Fetch current KAS price for cap calculation
    let kas_price = fetch_kas_price_coingecko().await.unwrap_or(0.12);
    let max_withdrawal_sompi = get_max_withdrawal_sompi(kas_price);
    
    // Check $1000 USD withdrawal cap
    if req.amount_sompi > max_withdrawal_sompi {
        return HttpResponse::BadRequest().json(WithdrawalSubmitResponse {
            success: false,
            request_id: 0,
            submitted_at: 0,
            unlocks_at: 0,
            l1_block_submitted: 0,
            seconds_remaining: 0,
            error: Some(format!("Withdrawal exceeds $1000 USD limit ({:.2} KAS @ ${:.4})", 
                max_withdrawal_sompi as f64 / 100_000_000.0, kas_price)),
        });
    }
    
    // Check circuit breaker
    if inner.circuit_breaker.is_tripped {
        return HttpResponse::ServiceUnavailable().json(WithdrawalSubmitResponse {
            success: false,
            request_id: 0,
            submitted_at: 0,
            unlocks_at: 0,
            l1_block_submitted: 0,
            seconds_remaining: 0,
            error: Some("Circuit breaker tripped - withdrawals paused".to_string()),
        });
    }
    
    // Record outflow and check if it trips breaker
    if inner.circuit_breaker.record_outflow(req.amount_sompi) {
        return HttpResponse::ServiceUnavailable().json(WithdrawalSubmitResponse {
            success: false,
            request_id: 0,
            submitted_at: 0,
            unlocks_at: 0,
            l1_block_submitted: 0,
            seconds_remaining: 0,
            error: Some("Withdrawal would exceed hourly limit".to_string()),
        });
    }
    
    // Compliance check (sanctions)
    {
        let mut gk = state.gatekeeper.write().await;
        if gk.check_ofac(&req.dest_address) {
            return HttpResponse::Forbidden().json(WithdrawalSubmitResponse {
                success: false,
                request_id: 0,
                submitted_at: 0,
                unlocks_at: 0,
                l1_block_submitted: 0,
                seconds_remaining: 0,
                error: Some("Destination address is sanctioned".to_string()),
            });
        }
    }
    
    // === L2 WALLET LOCK: Prevent double-spend during 24h settlement ===
    // Lock the withdrawal amount in user's L2 wallet immediately
    // This moves KAS from available_balance to locked_withdrawal_balance
    // The Merkle tree is NOT updated until the 24h timer clears
    if let Some(user) = inner.users.get_mut(&req.user_pubkey) {
        if let Err(e) = user.lock_for_withdrawal(req.amount_sompi) {
            return HttpResponse::BadRequest().json(WithdrawalSubmitResponse {
                success: false,
                request_id: 0,
                submitted_at: 0,
                unlocks_at: 0,
                l1_block_submitted: 0,
                seconds_remaining: 0,
                error: Some(format!("L2 wallet lock failed: {}", e)),
            });
        }
    } else {
        return HttpResponse::NotFound().json(WithdrawalSubmitResponse {
            success: false,
            request_id: 0,
            submitted_at: 0,
            unlocks_at: 0,
            l1_block_submitted: 0,
            seconds_remaining: 0,
            error: Some("User not found".to_string()),
        });
    }
    
    let now = current_timestamp();
    let request_id = now ^ (req.amount_sompi << 16);
    let unlocks_at = now + WITHDRAWAL_DELAY_SECONDS;
    
    let pending = PendingWithdrawal {
        request_id,
        user_pubkey: req.user_pubkey.clone(),
        amount_sompi: req.amount_sompi,
        dest_address: req.dest_address.clone(),
        submitted_at: now,
        unlocks_at,
        l1_block_submitted: 12345678 + inner.pending_withdrawals.len() as u64,
        status: WithdrawalStatus::Pending,
    };
    
    inner.pending_withdrawals.insert(request_id, pending);
    
    HttpResponse::Ok().json(WithdrawalSubmitResponse {
        success: true,
        request_id,
        submitted_at: now,
        unlocks_at,
        l1_block_submitted: 12345678,
        seconds_remaining: WITHDRAWAL_DELAY_SECONDS,
        error: None,
    })
}

/// POST /api/subscription/pay - Pay monthly subscription
pub async fn api_subscription_pay(
    state: web::Data<FrontendAppState>,
    req: web::Json<SubscriptionPayRequest>,
) -> impl Responder {
    let mut inner = state.inner.write().await;
    let response = inner.subscription_tracker.record_payment(&req.user_pubkey, req.xp);
    
    // Update user subscription
    if let Some(user) = inner.users.get_mut(&req.user_pubkey) {
        user.subscription_expires_at = Some(response.expires_at);
    }
    
    // ============================================================================
    // COUPON RENEWAL: Re-enable host's coupons on subscription payment
    // ============================================================================
    // When merchant pays monthly subscription, their coupons are renewed
    // Expired coupons get new 30-day expiration from NOW
    // This ties coupon validity to active subscription
    let coupons_renewed = renew_host_coupons(&req.user_pubkey, response.expires_at);
    
    HttpResponse::Ok().json(serde_json::json!({
        "success": response.success,
        "tier": response.tier,
        "fee_type": response.fee_type,
        "fee_sompi": response.fee_sompi,
        "fee_kas": response.fee_kas,
        "paid_at": response.paid_at,
        "expires_at": response.expires_at,
        "coupons_renewed": coupons_renewed
    }))
}

