/// POST /api/frost/deposit - Deposit to communal wallet
pub async fn api_frost_deposit(
    state: web::Data<FrontendAppState>,
    req: web::Json<serde_json::Value>,
) -> impl Responder {
    let amount = req.get("amount_sompi")
        .and_then(|v| v.as_u64())
        .unwrap_or(0);
    
    let source_address = req.get("user_pubkey")
        .and_then(|v| v.as_str())
        .unwrap_or("");
    
    if amount == 0 {
        return HttpResponse::BadRequest().json(serde_json::json!({
            "success": false,
            "error": "Invalid amount"
        }));
    }
    
    // SANCTIONS CHECK: Screen source address before accepting deposit
    {
        let mut gk = state.gatekeeper.write().await;
        if gk.check_ofac(&source_address) {
            return HttpResponse::Forbidden().json(serde_json::json!({
                "success": false,
                "error": "Source address is sanctioned. Deposit rejected."
            }));
        }
    }
    
    // Fetch current KAS price
    let kas_price = fetch_kas_price_coingecko().await.unwrap_or(0.12);
    let max_deposit_usd = 1000.0;
    
    // Check if CURRENT balance already exceeds $1000 USD (price rise scenario)
    let wallet = state.frost_wallet.read().await;
    let current_balance_usd = (wallet.balance as f64 / 100_000_000.0) * kas_price;
    
    if current_balance_usd > max_deposit_usd {
        return HttpResponse::BadRequest().json(serde_json::json!({
            "success": false,
            "error": format!(
                "Balance limit exceeded: ${:.2} USD > ${:.2} USD. Withdraw KASPA before depositing more.",
                current_balance_usd, max_deposit_usd
            )
        }));
    }
    drop(wallet);
    
    // Check if this new deposit amount exceeds $1000 USD
    let max_deposit_sompi = get_max_deposit_sompi(kas_price);
    
    if amount > max_deposit_sompi {
        return HttpResponse::BadRequest().json(serde_json::json!({
            "success": false,
            "error": format!("Deposit exceeds $1000 USD limit ({:.2} KAS @ ${:.4})", 
                max_deposit_sompi as f64 / 100_000_000.0, kas_price)
        }));
    }
    
    let mut wallet = state.frost_wallet.write().await;
    match wallet.deposit(amount) {
        Ok(()) => HttpResponse::Ok().json(serde_json::json!({
            "success": true,
            "new_balance_sompi": wallet.balance,
            "new_balance_kas": wallet.balance as f64 / SOMPI_PER_KAS as f64,
        })),
        Err(e) => HttpResponse::BadRequest().json(serde_json::json!({
            "success": false,
            "error": e
        })),
    }
}

/// Configure all frontend API routes - WITH XP ENDPOINTS
pub fn configure_frontend_api(cfg: &mut web::ServiceConfig) {
    cfg.service(
        web::scope("/api")
            .route("/health", web::get().to(api_health))
            .route("/register", web::post().to(api_register))
            .route("/apartment/search", web::post().to(api_apartment_search))
            .route("/withdrawal/submit", web::post().to(api_withdrawal_submit))
            .route("/subscription/pay", web::post().to(api_subscription_pay))
            .route("/consignment/create", web::post().to(api_consignment_create))
            .route("/consignment/hold", web::post().to(api_consignment_hold))
            // XP/Reputation endpoints
            .route("/xp/{pubkey}", web::get().to(api_get_xp))
            .route("/xp/verify", web::post().to(api_verify_xp))
            .route("/reputation/{pubkey}", web::get().to(api_get_reputation))
            // L1 Inscription endpoints
            .route("/inscription/submit", web::post().to(api_submit_inscription))
            .route("/inscription/preview", web::get().to(api_preview_inscription))
            // Withdrawal inscription endpoints (user stats in L1 UTXO)
            .route("/withdrawal/inscribe", web::post().to(api_withdrawal_inscribe))
            .route("/withdrawal/inscription/preview/{pubkey}/{amount}", web::get().to(api_withdrawal_inscription_preview))
            .route("/balance/{pubkey}", web::get().to(api_get_balance))
            .route("/state/root", web::get().to(api_get_state_root))
            // FROST wallet endpoints
            .route("/frost/wallet", web::get().to(api_get_frost_wallet))
            .route("/frost/deposit", web::post().to(api_frost_deposit))
            // NEW: Sanctions handshake for pre-flight checks
            .route("/sanctions/handshake", web::post().to(api_sanctions_handshake))
            .route("/sanctions/check", web::post().to(api_sanctions_handshake))
    );
}

/// Start frontend API server
pub async fn start_frontend_api_server(listen_addr: &str) -> Result<(), String> {
    let state = web::Data::new(FrontendAppState::new_with_sanctions().await);
    
    // Start background task to refresh sanctions list every 24 hours
    FrontendAppState::start_sanctions_refresh_task(state.clone());
    
    HttpServer::new(move || {
        let cors = Cors::default()
            .allow_any_origin()
            .allow_any_method()
            .allow_any_header()
            .max_age(3600);
        
        App::new()
            .app_data(state.clone())
            .wrap(Logger::default())
            .wrap(cors)
            .configure(configure_frontend_api)
    })
    .bind(listen_addr)
    .map_err(|e| format!("Server bind error: {}", e))?
    .run()
    .await
    .map_err(|e| format!("Server error: {}", e))?;
    
    Ok(())
}

